  ?p a brick:ElectricPowerSensor .
  OPTIONAL{ ?p rdfs:label ?lbl }
}
LIMIT 200

SELECT DISTINCT ?sensor ?parent ?parent_label WHERE {
  ?sensor a brick:ElectricPowerSensor .
  ?sensor brick:hasParent ?parent .
  OPTIONAL{ ?parent rdfs:label ?parent_label }
}
LIMIT 200

SELECT ?s ?p ?o WHERE {
  ?s ?p ?o .
  FILTER( str( ?p ) = "http://www.w3.org/1999/02/22-rdf-syntax-ns#type" )
  FILTER( str(?o) LIKE "%PowerSensor%" || str(?o) LIKE "%power%" )
}
LIMIT 5

